1	package vault
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11	)
12	
13	// GCCandidate is a content object no longer referenced by the current name
14	// mapping or any snapshot, and therefore eligible for deletion.
15	type GCCandidate struct {
16		Digest string
17		Size   int64
18	}
19	
20	// GCReport summarizes one garbage collection pass. Candidates is always the
21	// full set of unreferenced objects found, sorted by digest; Deleted and Bytes
22	// record what was actually removed (zero for a dry run).
23	type GCReport struct {
24		Candidates []GCCandidate
25		Deleted    int
26		Bytes      int64
27	}
28	
29	// GC removes content objects that neither the current name mapping nor any
30	// saved snapshot still references. With dryRun set, nothing is deleted and
31	// the report only lists the candidates. The whole pass runs under the
32	// exclusive repository lock, so it always observes a complete, quiescent
33	// state: concurrent uploads, snapshot operations, downloads, and verifies
34	// either finish before the pass starts or wait until it is done.
35	//
36	// GC never creates or initializes a repository, never rewrites the index or
37	// any snapshot, and only ever deletes regular files directly inside objects/
38	// whose names are valid digests. Any unreadable or malformed reference
39	// (index or snapshot) aborts the pass before anything is deleted. If a
40	// deletion fails, the pass stops immediately; objects already removed stay
41	// removed and the rest remain as candidates for the next run.
42	func (s *Store) GC(dryRun bool) (GCReport, error) {
43		if strings.TrimSpace(s.root) == "" {
44			return GCReport{}, errors.New("root is required")
45		}
46		// withLock would create a missing root for mutating operations; GC must
47		// refuse an absent or uninitialized repository instead.
48		info, err := os.Stat(s.root)
49		switch {
50		case errors.Is(err, os.ErrNotExist):
51			return GCReport{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
52		case err != nil:
53			return GCReport{}, err
54		case !info.IsDir():
55			return GCReport{}, fmt.Errorf("repository root %q is not a directory", s.root)
56		}
57		var report GCReport
58		err = s.withLock(true, func() error {
59			var gcErr error
60			report, gcErr = s.gcLocked(dryRun)
61			return gcErr
62		})
63		return report, err
64	}
65	
66	func (s *Store) gcLocked(dryRun bool) (GCReport, error) {
67		referenced, err := s.collectReferences()
68		if err != nil {
69			return GCReport{}, err
70		}
71		objectsDir := filepath.Join(s.root, "objects")
72		info, err := os.Lstat(objectsDir)
73		if err != nil {
74			return GCReport{}, fmt.Errorf("cannot inspect objects directory: %w", err)
75		}
76		if info.Mode()&os.ModeSymlink != 0 {
77			return GCReport{}, fmt.Errorf("objects path %q is a symbolic link", objectsDir)
78		}
79		if !info.IsDir() {
80			return GCReport{}, fmt.Errorf("objects path %q is not a directory", objectsDir)
81		}
82		dirents, err := os.ReadDir(objectsDir)
83		if err != nil {
84			return GCReport{}, fmt.Errorf("cannot read objects directory: %w", err)
85		}
86		candidates := []GCCandidate{}
87		for _, dirent := range dirents {
88			// Only regular files named by a valid digest are collectable;
89			// temp files, other names, subdirectories, and symlinks stay.
90			if !dirent.Type().IsRegular() || !isDigest(dirent.Name()) {
91				continue
92			}
93			if _, ok := referenced[dirent.Name()]; ok {
94				continue
95			}
96			fi, err := dirent.Info()
97			if err != nil {
98				return GCReport{}, fmt.Errorf("cannot stat object %q: %w", dirent.Name(), err)
99			}
100			candidates = append(candidates, GCCandidate{Digest: dirent.Name(), Size: fi.Size()})
101		}
102		sort.Slice(candidates, func(i, j int) bool { return candidates[i].Digest < candidates[j].Digest })
103		report := GCReport{Candidates: candidates}
104		if dryRun {
105			return report, nil
106		}
107		for _, candidate := range candidates {
108			if err := os.Remove(s.objectPath(candidate.Digest)); err != nil {
109				return report, fmt.Errorf("deleted %d objects (%d bytes), then failed to delete object %s: %w",
110					report.Deleted, report.Bytes, candidate.Digest, err)
111			}
112			report.Deleted++
113			report.Bytes += candidate.Size
114		}
115		return report, nil
116	}
117	
118	// collectReferences gathers every digest referenced by the current index and
119	// by all saved snapshots. Any record that cannot be read or fails validation
120	// is an error: GC must never guess whether a reference exists.
121	func (s *Store) collectReferences() (map[string]struct{}, error) {
122		referenced := map[string]struct{}{}
123		idx, err := s.loadStrict()
124		if err != nil {
125			return nil, fmt.Errorf("cannot collect references: current index is unusable: %w", err)
126		}
127		for key, entry := range idx.Entries {
128			if err := validateEntryRecord(key, entry); err != nil {
129				return nil, fmt.Errorf("current index is invalid: %w", err)
130			}
131			referenced[entry.Digest] = struct{}{}
132		}
133		// Every snapshot record is enumerated and validated exactly as list and
134		// restore see it: a damaged or unreadable record aborts reference
135		// collection before anything is deleted.
136		err = s.walkSnapshotRecords(func(_ string, snap Snapshot) error {
137			for _, entry := range snap.Entries {
138				referenced[entry.Digest] = struct{}{}
139			}
140			return nil
141		})
142		if err != nil {
143			return nil, err
144		}
145		return referenced, nil
146	}
147	
148	// loadStrict reads the current index for GC. Unlike load it rejects a
149	// missing or null entries mapping, since GC cannot distinguish "no entries"
150	// from "references lost" in that case.
151	func (s *Store) loadStrict() (index, error) {
152		data, err := os.ReadFile(s.indexPath())
153		if errors.Is(err, os.ErrNotExist) {
154			return index{}, fmt.Errorf("repository %q is not initialized: index.json is missing", s.root)
155		}
156		if err != nil {
157			return index{}, err
158		}
159		var idx index
160		if err := json.Unmarshal(data, &idx); err != nil {
161			return index{}, err
162		}
163		if idx.Entries == nil {
164			return index{}, errors.New("missing entries mapping")
165		}
166		return idx, nil
167	}
168	
169	// validateEntryRecord checks one index or snapshot entry the same way
170	// restore validates snapshot entries: the map key must equal the recorded
171	// name, the name must be legal, the digest must be 64 lowercase hex
172	// characters, and the size must not be negative.
173	func validateEntryRecord(key string, entry Entry) error {
174		if entry.Name != key {
175			return fmt.Errorf("entry %q is filed under %q", entry.Name, key)
176		}
177		if err := validateName(entry.Name); err != nil {
178			return fmt.Errorf("invalid entry name %q", entry.Name)
179		}
180		if !isDigest(entry.Digest) {
181			return fmt.Errorf("entry %q has digest %q, want 64 lowercase hex characters", entry.Name, entry.Digest)
182		}
183		if entry.Size < 0 {
184			return fmt.Errorf("entry %q has negative size %d", entry.Name, entry.Size)
185		}
186		return nil
187	}
