474			t.Fatal(err)
475		}
476		if _, err := store.CreateSnapshot("base"); err != nil {
477			t.Fatal(err)
478		}
479		const workers = 6
480		var wg sync.WaitGroup
481		errs := make(chan error, workers*2)
482		for i := 0; i < workers; i++ {
483			wg.Add(2)
484			go func(i int) {
485				defer wg.Done()
486				input := writeFile(t, fmt.Sprintf("payload-%d", i))
487				if _, err := New(root).Put(fmt.Sprintf("artifact-%d.txt", i), input); err != nil {
488					errs <- err
489				}
490			}(i)
491			go func() {
492				defer wg.Done()
493				if _, err := New(root).GC(false); err != nil {
494					errs <- err
495				}
496			}()
497		}
498		wg.Wait()
499		close(errs)
500		for err := range errs {
501			t.Fatal(err)
502		}
503		// Whatever the interleaving, every referenced object must be intact and
504		// a final GC must find nothing or only genuinely orphaned objects.
505		if _, err := store.Verify(); err != nil {
506			t.Fatal(err)
507		}
508		if err := store.RestoreSnapshot("base"); err != nil {
509			t.Fatal(err)
510		}
511		report, err := store.GC(false)
512		if err != nil {
513			t.Fatal(err)
514		}
515		again, err := New(root).GC(true)
516		if err != nil {
517			t.Fatal(err)
518		}
519		if len(again.Candidates) != 0 {
520			t.Fatalf("candidates after GC: %+v (deleted %d)", again.Candidates, report.Deleted)
