		return nil, fmt.Errorf("invalid package: unknown format %q", raw.Format)
	}
	if raw.Version != packageVersion {
		return nil, fmt.Errorf("invalid package: unsupported version %d (supported: %d)", raw.Version, packageVersion)
	}
